import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long mod = 1000000007L;
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 0) {
            System.out.println(pow(p, p - 1, mod));
        } else if (k == 1) {
            System.out.println(pow(p, p, mod));
        } else {
            java.util.ArrayList<Long> z = new java.util.ArrayList<>();
            z.add(1L);
            while (true) {
                long last = z.get(z.size() - 1);
                long nextVal = (last * k) % p;
                if (nextVal == z.get(0)) {
                    break;
                }
                z.add(nextVal);
            }
            System.out.println(pow(p, (p - 1) / z.size(), mod));
        }
        scanner.close();
    }

    private static long pow(long base, long exp, long mod) {
        long result = 1L;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
